import json

# A tiny contract: field name -> expected Python type
CONTRACT = {
    "id": int,
    "name": str,
    "email": str,
}


def validate(payload: dict, contract: dict) -> list[str]:
    errors = []
    for field, expected_type in contract.items():
        if field not in payload:
            errors.append(f"missing field: {field}")
            continue
        if not isinstance(payload[field], expected_type):
            errors.append(f"{field} should be {expected_type.__name__}")
    return errors


responses = [
    {"id": 1, "name": "Ana", "email": "ana@example.com"},
    {"id": "2", "name": "Luis", "email": "luis@example.com"},
]

for i, response in enumerate(responses, start=1):
    errors = validate(response, CONTRACT)
    status = "VALID" if not errors else "INVALID"
    print(f"Response {i}: {status}")
    for e in errors:
        print(f"  - {e}")
